import 'package:flutter/material.dart';import 'package:geolocator/geolocator.dart';import 'product_service.dart';class ProductUploadScreen extends StatefulWidget{const ProductUploadScreen({super.key});@override State<ProductUploadScreen> createState()=>_S();}class _S extends State<ProductUploadScreen>{final title=TextEditingController(),description=TextEditingController(),price=TextEditingController(),image=TextEditingController(),location=TextEditingController();String category='Lainnya';bool loading=false;Future<void> save()async{if(title.text.trim().isEmpty||price.text.isEmpty)return;setState(()=>loading=true);try{double lat=0,lng=0;try{final p=await Geolocator.getCurrentPosition();lat=p.latitude;lng=p.longitude;}catch(_){}await ProductService().createProduct(title:title.text,description:description.text,price:int.tryParse(price.text)??0,imageUrl:image.text,latitude:lat,longitude:lng,category:category,locationName:location.text);if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Iklan berhasil diterbitkan')));Navigator.pop(context);}}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Pasang Iklan')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Jual barang Anda ke pembeli di sekitar.',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),TextField(controller:title,decoration:const InputDecoration(labelText:'Judul iklan')),DropdownButtonFormField(value:category,items:['Lainnya','Mobil','Motor','Properti','Elektronik','Fashion','Rumah Tangga','Hobi'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>category=v!)),TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Harga')),TextField(controller:location,decoration:const InputDecoration(labelText:'Nama kota / lokasi')),TextField(controller:description,maxLines:5,decoration:const InputDecoration(labelText:'Deskripsi')),TextField(controller:image,decoration:const InputDecoration(labelText:'URL foto')),const SizedBox(height:20),FilledButton.icon(onPressed:loading?null:save,icon:const Icon(Icons.publish),label:Text(loading?'Menerbitkan...':'Terbitkan Iklan'))]));}}